import type { Config } from "tailwindcss";
import us from "./lib/uswds-theme.json";

// U.S. Web Design System theme. Every value comes from lib/uswds-theme.json,
// generated by scripts/uswds-theme.mjs from the official @uswds/uswds package
// with Agora's theme settings (warm neutrals, ink actions, square corners). USWDS token names are first-class: "bg-primary-dark",
// "text-base-dark", "border-base-lighter", "bg-success-lighter". Type follows
// USWDS's scale per role ("text-heading-xl" with "font-heading", "text-ui-xs"),
// normalized by cap height as USWDS does. Agora's older color names map onto
// USWDS theme tokens so every page follows the system.

type Tree = string | { [k: string]: Tree };
const v = (name: string) => `rgb(var(--us-${name}) / <alpha-value>)`;
const toVars = (tree: Record<string, Tree>): Record<string, Tree> =>
  Object.fromEntries(Object.entries(tree).map(([k, val]) => [k, typeof val === "string" ? v(val) : toVars(val)]));
const t = us.color.theme;
const sizes = (role: "heading" | "body" | "ui"): Record<string, [string, { lineHeight: string }]> =>
  Object.fromEntries(Object.entries(us.font.sizes[role]).map(([k, v]) => [`${role}-${k}`, [v, { lineHeight: String(role === "heading" ? us.font.headingLineHeight : role === "ui" ? 1.35 : us.font.bodyLineHeight) }]]));

export default {
  content: ["./app/**/*.{ts,tsx}", "./components/**/*.{ts,tsx}"],
  theme: {
    extend: {
      // Every color is a CSS variable from app/theme.css, so light and dark both come
      // from the generated palette. The <alpha-value> keeps opacity modifiers working.
      colors: toVars(us.palette),
      fontFamily: {
        sans: [`"${us.font.families.sans}"`, '"Source Sans Pro"', "Helvetica Neue", "Helvetica", "Roboto", "Arial", "sans-serif"],
        body: [`"${us.font.families.sans}"`, '"Source Sans Pro"', "Helvetica Neue", "Helvetica", "Roboto", "Arial", "sans-serif"],
        ui: [`"${us.font.families.sans}"`, '"Source Sans Pro"', "Helvetica Neue", "Helvetica", "Roboto", "Arial", "sans-serif"],
        // The heading role follows the theme: sans in Agora's theme, serif in USWDS's default.
        heading: us.font.roles.heading === "serif" ? [`"${us.font.families.serif}"`, "Georgia", "Cambria", '"Times New Roman"', "Times", "serif"] : [`"${us.font.families.sans}"`, '"Source Sans Pro"', "Helvetica Neue", "Helvetica", "Arial", "sans-serif"],
        mono: [`"${us.font.families.mono}"`, "Bitstream Vera Sans Mono", "Consolas", "Courier", "monospace"],
      },
      fontSize: { ...sizes("heading"), ...sizes("body"), ...sizes("ui") },
      // Corners from the theme's shape settings (square in Agora's theme). Dots and avatars keep rounded-full.
      borderRadius: { sm: `${us.shape.tag}px`, DEFAULT: `${us.shape.button}px`, md: `${us.shape.button}px`, lg: `${us.shape.card}px`, xl: `${us.shape.card}px`, "2xl": `${us.shape.card}px`, "3xl": `${us.shape.card}px` },
      // Small spaced labels, as retail sites use for categories and makers.
      letterSpacing: { label: "0.08em" },
      // USWDS shadow tokens 1–5.
      boxShadow: {
        card: "0 1px 0.25rem 0 rgba(0, 0, 0, 0.1)",
        1: "0 1px 0.25rem 0 rgba(0, 0, 0, 0.1)",
        2: "0 0.25rem 0.5rem 0 rgba(0, 0, 0, 0.1)",
        3: "0 0.5rem 1rem 0 rgba(0, 0, 0, 0.1)",
        4: "0 0.75rem 1.5rem 0 rgba(0, 0, 0, 0.1)",
        5: "0 1rem 2rem 0 rgba(0, 0, 0, 0.1)",
      },
    },
  },
  plugins: [],
} satisfies Config;
